key_code                 = $0109 ; Last key from scan_keyboard: matrix index column*8 + row, bit 7 = shift, $FF = none. Used: read 4, written 2.
key_scan_code            = $010a ; Key code of the current scan ($FF = none, $6F = not a game key), scan_keyboard / decode_*_key. Used: read 3, written 5.
key_shift                = $010b ; Nonzero when a shift key is down during the scan. Used: read 1, written 1, modified 1.
key_ready                = $010c ; 1 = a new code waits in key_code; the reader (title_menu_loop, handle_game_keys, check_demo_abort) clears it. scan_keyboard does nothing while it is set. Used: read 4, written 5.
key_columns              = $010d ; Column bits read with all keyboard rows low (scan_keyboard), shifted by decode_any_key. Used: written 1, modified 1.
key_scan_mode            = $010e ; 0 = decode any key (title), nonzero = only F1, S, SPACE and V (game and demo). Used: read 1, written 3.
mover_dir                = $010f ; Room 13 floor movers, slot 0-9 (slot 9 is never processed): 0 = off, $02 = moves left, $82 = moves right (bit 7). room13_init sets, update_floor_movers reads. Used: read 2, written 4.
mover_col                = $0119 ; Room 13 floor movers: column of slot 0-9. Used: read 3, written 10, modified 2.
mover_row                = $0123 ; Room 13 floor movers: text row of slot 0-9. Used: read 1, written 8.
mover_old_col            = $012d ; Room 13 floor movers: previous column of slot 0-9. Used: written 9.
mover_min_col            = $0137 ; Room 13 floor movers: lowest column of slot 0-9 (a left mover wraps below it). Used: read 2, written 8.
mover_wrap_col           = $0141 ; Room 13 floor movers: wrap column of slot 0-9 (highest column; a left mover restarts here). Used: read 2, written 8.
room13_band_bonus        = $014b ; Room 13 height band bonus flags, index player*4 + band (bands 0-2 used): 1 = 500 points still there. init_game_variables and room19_frame set 1, room13_frame decrements. Used: read 3, written 2, modified 3.
room_band_colours        = $0153 ; Raster band colours of the room: 4 triplets BGCOL0/BGCOL1/BGCOL2. draw_room copies 20 bytes from the block of room_aux_ptr, irq_game_bottom rewrites $0153-$015E every frame from room_palette_ptr, irq_game_playfield / irq_game_colour_split write them to the VIC, the screen saver saves and masks them. $015F-$0166 have no reader. Used: read 7, written 4.
random_table             = $0200 ; 256 random bytes from SID voice 3 noise, made by cold_start. random_byte does not read it (random_ptr high byte is 0 in play). Used: written 1, address 2.
room_unvisited           = $0300 ; First-visit flags, index room*2 + player: 1 = not entered yet. draw_room gives 2000 points and clears it; init_game_variables and reset_unvisited_rooms set them (room 0 cleared). Used: read 1, written 5, modified 1.
parked_lantern_flags     = $0340 ; Parked lantern flags: one byte per lantern record of all 20 rooms in room order (97 bytes), the lantern states of the player who is not playing in a two-player game. init_game_variables sets all to 1 (fill_parked_lanterns); swap_player_lanterns exchanges them with byte 0 of the records of the lantern lists when the turn passes. The image bytes are overwritten before any read. Used: written 1, address 2.

; BASIC program RAM $0800-$9fff
; RAM for programs; a BASIC program starts at $0801. The application decides what is here.
contact_col0             = $4eed ; Background contact tables of check_background_contact, one per mask column (23 bytes each). Index 0-15 = a 4-bit value made of two multicolour pixel codes of a background char under set sprite pixels (high nibble and low nibble of charset byte AND mask). A nonzero entry means the pair was seen. Entries 16-22 hold the pairs 3, 7, 11, 12, 13, 14, 15 (pairs with a %11 pixel) seen in chars whose colour RAM colour is not 0; the swap routines move them there. Image residue: $4EED-$4F3D hold a copy of the message bytes $4731-$4781 of an earlier build. At $4F2C the copy reads "DATASO", 6 zero bytes, "SENTS", $A0: the original text "DATASOFT PRESENTS" of message $62 (msg_presents), which this release changed to "DIABOLO  PRESENTS". init_game_variables clears it. Used: read 47, written 18.
contact_col1             = $4f04 ; Used: read 45, written 17.
contact_col2             = $4f1b ; Used: read 46, written 17.
contact_col0_lit         = $4f32 ; 1 while the current char of mask column 0/1/2 has a colour RAM colour (bits 0-2) other than 0. While it is 1 the column table is in the swapped state: new %11 hits of coloured chars land in entries 3-15 and the %11 hits of colour-0 chars wait in entries 16-22. Used: read 5, written 2, modified 3.
contact_col1_lit         = $4f33 ; Used: read 4, written 2, modified 3.
contact_col2_lit         = $4f34 ; Used: read 4, written 2, modified 3.
contact_lit_saved        = $4f35 ; Copy of contact_col0_lit..contact_col2_lit while the upper-body result is evaluated. Used: read 3, written 1.
contact_upper_end_row    = $4f38 ; Mask row at which the upper-body result (actor_contact_upper) is taken: contact_last_row - 6. Used: read 1, written 1.
contact_last_row         = $4f39 ; Mask row after the last one scanned: pixel row in char (contact_pixel_y) + $15. Used: read 1, written 1.
contact_char_row_end     = $4f3a ; Mask row at which the scan moves to the next char row (8, 16, 24, 32). Used: read 1, written 4.
contact_count_c01        = $4f3c ; Result counters of evaluate_contact: nonzero = the mask touches background pixels of code %01, %10, %11 in a coloured char, %11 in a char with colour 0. Packed into actor_contact,x / actor_contact_upper,x bits 0-3. Used: written 1, modified 2.
contact_count_c10        = $4f3d ; Used: modified 2.
contact_count_c11_lit    = $4f3e ; Used: modified 2.
contact_count_c11_dark   = $4f3f ; Used: modified 2.
sprite_owner             = $4f40 ; Owner actor of hardware sprites 0-4 (5 bytes, index = sprite number; $FF = free). set_sprite_slot_owner maps a collision code 3-7 to its sprite through collision_code_to_sprite and stores the actor there; reset_play_state sets all to $FF, remove_actor frees the actor's sprites, check_fight_collisions reads the owner of each sprite in a sprite-sprite collision. Used: read 1, written 4.
fall_attack_budget       = $4f45 ; Per-actor count of fall attacks that can still hit (3 bytes): check_fight_fall uses one each time the actor lands on another one from $0A or more above (fall attack, state $0E) and gives no hit when it is 0. frame_update refills all three to 2 when fall_attack_refill_timer reaches 0 (every 256 frames). Used: read 1, written 4.
actor_pose               = $4f48 ; Animation pose of each actor (3 bytes, even number) chosen by select_actor_pose / set_actor_pose; actor_pose_b = pose + 1. Used: read 4, written 3.
actor_pose_b             = $4f4b ; Used: read 1, written 4.
actor_frame_a            = $4f4e ; Frame numbers of the two sprites of each actor: pose + actor_frame_base[actor type] (set_actor_pose). They index frame_gfx_lo/hi (sprite graphics) and contact_mask_addr_lo/hi (contact masks); check_background_contact uses actor_frame_a. Used: read 3, written 4.
actor_frame_b            = $4f51 ; Used: written 4.
actor_prev_pose          = $4f54 ; actor_pose of each actor before the current pose update. Used: read 4, written 1.
actor_move_queue         = $4f57 ; Delayed movement queue: 11 records of 4 step counters (one per direction) x 3 actors, interleaved (counter d of record r for actor x at actor_move_queue + 12r + 3d + x). Record 0 collects new steps; actor_action_step pushes it into the queue, performs record 1 (actor_undo_up_loop: actor_move_down, actor_move_up, actor_move_right, actor_move_left) and shifts the queue down. draw_room clears it. Used: read 12, written 19, modified 10.
actor_pose_done          = $4fdb ; Per-actor flag: nonzero = the pose was already picked in this update (set by select_actor_pose, actor_set_idle and apply_fight_hits, cleared by actor_action_run). Used: read 1, written 1, modified 3.
burst_trap_timer         = $4fde ; Burst trap slots (3): timer (0 = free; touch_trap_tile starts it at 1, update_burst_traps counts it up and draws the burst at 8, 12, 16 and 20 and frees the slot at 24), column - 1 and text line - 1 of the trap (set by touch_trap_tile). Used: read 4, written 7, modified 1.
burst_trap_col           = $4fe1 ; Used: read 6, written 3, modified 3.
burst_trap_row           = $4fe4 ; Used: read 6, written 3, modified 3.
sprite_buf_a_spr0        = $8180 ; Sprite blocks $06-$0F (64 bytes each), written at run time; the image bytes do not matter. The sprite builder copy_sprite_frame draws the actors here, buffer A (blocks $06-$0A) and buffer B (blocks $0B-$0F) in turn (sprite_buffer_select selects; sprite_buffer_addresses holds the block addresses, sprite_buffer_pointers the block numbers for sprite_pointers+0..4). Sprite block $06: image of hardware sprite 0 (actor 0 = Bruce, first sprite), buffer A. Used: written 2, table 1.
sprite_buf_a_spr1        = $81c0 ; Sprite block $07: image of hardware sprite 1 (actor 0 = Bruce, second sprite), buffer A. Used: table 1.
sprite_buf_a_spr2        = $8200 ; Sprite block $08: image of hardware sprite 2 (actor 1 = Yamo, first sprite), buffer A. Used: written 1, table 1.
sprite_buf_a_spr3        = $8240 ; Sprite block $09: image of hardware sprite 3 (actor 1 = Yamo, second sprite), buffer A. Used: table 1.
sprite_buf_a_spr4        = $8280 ; Sprite block $0A: image of hardware sprite 4 (actor 2 = Ninja, his only sprite), buffer A. Used: written 2, table 1.
sprite_buf_b_spr0        = $82c0 ; Sprite block $0B: image of hardware sprite 0 (actor 0 = Bruce, first sprite), buffer B. Used: written 1, table 1.
sprite_buf_b_spr1        = $8300 ; Sprite block $0C: image of hardware sprite 1 (actor 0 = Bruce, second sprite), buffer B. Used: written 1, table 1.
sprite_buf_b_spr2        = $8340 ; Sprite block $0D: image of hardware sprite 2 (actor 1 = Yamo, first sprite), buffer B. In room 18 launch_fireball0 points sprite 6 here and update_fireballs / clear_fireball_sprites write rows 0-3. Used: written 4, address 1, table 1.
sprite_buf_b_spr3        = $8380 ; Sprite block $0E: image of hardware sprite 3 (actor 1 = Yamo, second sprite), buffer B. In room 18 launch_fireball1 points sprite 7 here and update_fireballs / clear_fireball_sprites write rows 0-3. Used: written 2, address 1, table 1.
sprite_buf_b_spr4        = $83c0 ; Sprite block $0F: image of hardware sprite 4 (actor 2 = Ninja, his only sprite), buffer B. On the title screen it holds the "TM" sprite: show_title_screen clears it (title_clear_sprite_loop) and copies 12 bytes from title_tm_sprite_rows to rows 4-7. Used: written 3, address 2, table 1.
text_font                = $8800 ; Charset of the title text and the status line (D018 = $32), built by cold_start (copy of the character ROM); the image bytes do not matter. Codes $00-$1F = ROM characters $20-$3F (space, punctuation, digits), $20-$3F = ROM $00-$1F (@, A-Z), $40-$5F and $60-$7F = the same two groups inverted. So code = ASCII - $20 for digits and capitals. Used: written 1.
text_font_letters        = $8900 ; Codes $20-$3F (ROM @, A-Z, [, pound, ], arrows). cold_start and reset_play_state fill code $20 with $FF (solid block in place of @). Used: written 3.
text_font_inverse        = $8a00 ; Codes $40-$5F: inverted space, punctuation and digits. Used: written 1.
text_font_keycap_left    = $8a10 ; Code $42, filled with $03 by cold_start: a bar on the right edge, the left end of an inverted key cap (title "F3" etc.). Used: written 1.
text_font_keycap_right   = $8ab0 ; Code $56, filled with $C0 by cold_start: a bar on the left edge, the right end of an inverted key cap. Used: written 1.
text_font_inverse_letters = $8b00 ; Codes $60-$7F: inverted @, A-Z and the rest of ROM characters $00-$1F. Used: written 1.
game_screen              = $8c00 ; Screen RAM ($8C00-$8FE7, 40x25) of the title and the game; the image bytes do not matter to the game. Game layout: row 0 empty, row 1 status line ("1UP 000000 TOP 000000 FALLS 04"), row 2 separator, rows 3-24 the room (11 tile rows of 2 screen rows). $8FE8-$8FF7 are spare; the room decoder writes 2 bytes there for rooms 4, 7, 10, 13, 17, 18. The image bytes $8C00-$8E84 are a fragment of an assembler symbol table from the build: 59 entries of [length byte, bit 7 = flag][name][address lo, hi], e.g. $88 "ADOWNL21" $4F14. They are the source labels of the actor frames (ADOWN, BDUCK, ALEAP, AJUMP, ACLIMB, AKICK, ASTOP, ARUN, YKICK, AYDOWN). The addresses of the Bruce labels plus $1462 are the frame addresses of this program; the only entry with bit 7 clear, ADWONL22, points to unused_frame_gfx. Used: read 8, written 39, address 13.
sprite_pointers          = $8ff8 ; Sprite pointers 0-7 (block number = address/64 - $200). Sprites 0-4 show the actor buffers ($06-$0A or $0B-$0F, written by show_actor_sprites); in room 18 sprites 6 and 7 get $0D/$0E from launch_fireball0/launch_fireball1; the title uses block $0F for the TM sprite. Used: written 7.

; BASIC ROM or RAM $a000-$bfff
; BASIC ROM when $01 bits 0 and 1 are set, else RAM. RAM under the ROM is application memory.
charset_rooms_0_9        = $a000 ; Expanded room charset (2 KB, 256 chars) of rooms 0-9, VIC $D018 = $38; built by cold_start from room_charset_a, flame chars patched by flicker_lantern_flames. Used: written 10, address 4.
charset_rooms_10_19      = $a800 ; Expanded room charset of rooms 10-17 and 19, $D018 = $3A; built from room_charset_b. Used: written 6, address 4.
charset_wizard           = $b000 ; Expanded room charset of room 18 (wizard), $D018 = $3C; built from room_charset_c. Used: address 3.
charset_wizard_flash     = $b800 ; Expanded charset from room_charset_d, $D018 = $3E: room 18 switches to it when the wizard is defeated. Used: address 3.

; Free RAM $c000-$cfff
; Free RAM. The application decides what is here.
shift_mask_col0          = $cae0 ; Column 0 (32 rows) of the shifted contact mask (build_shift_mask, scan_mask_rows); at cold start build_contact_masks uses $CAE0-$CB3F as the 96-byte buffer of the odd frame. Used: read 2, written 4, modified 2.
shift_mask_col1          = $cb00 ; Column 1 of the shifted contact mask (build_shift_mask, scan_mask_rows). Used: read 1, modified 2.
shift_mask_col2          = $cb20 ; Column 2 of the shifted contact mask. Used: read 1, modified 2.
shift_mask_col3          = $cb40 ; Column 3 of the shifted contact mask: it receives the mask's column 2 when contact_pixel_x = 3 (copied one column right, then shifted left one pixel). scan_mask_rows does not test it. Used: modified 1.

; VIC-II registers $d000-$d3ff
SP0X                     = $d000 ; Sprite 0 X position, bits 0-7 (bit 8 is in $D010). Used: written 7.
SP0Y                     = $d001 ; Sprite 0 Y position. Used: written 7.
SP6X                     = $d00c ; Sprite 6 X position, bits 0-7 (bit 8 is in $D010). Used: written 1.
SP6Y                     = $d00d ; Sprite 6 Y position. Used: written 1.
MSIGX                    = $d010 ; Bit 8 of the X position of each sprite (bit n = sprite n). Used: read 5, written 6.
SCROLY                   = $d011 ; Control 1: vertical scroll (bits 0-2), 25/24 rows (bit 3), display enable (bit 4), bitmap mode (bit 5), extended color mode (bit 6), raster line bit 8 (bit 7). Used: read 25, written 25.
RASTER                   = $d012 ; Read: raster line bits 0-7. Write: raster interrupt line bits 0-7. Used: read 5, written 9.
SPENA                    = $d015 ; Sprite enable (bit n = sprite n). Used: read 9, written 17.
SCROLX                   = $d016 ; Control 2: horizontal scroll (bits 0-2), 40/38 columns (bit 3), multicolor mode (bit 4). Used: written 7.
YXPAND                   = $d017 ; Sprite double height (bit n = sprite n). Used: written 3.
VMCSB                    = $d018 ; Memory setup: character or bitmap base (bits 1-3), screen memory (bits 4-7), inside the VIC-II bank. Used: written 7.
VICIRQ                   = $d019 ; Interrupt flags: raster (bit 0), sprite-background (bit 1), sprite-sprite (bit 2), light pen (bit 3), any (bit 7). Write 1 to clear a flag. Used: written 9.
IRQMSK                   = $d01a ; Interrupt enable: raster (bit 0), sprite-background (bit 1), sprite-sprite (bit 2), light pen (bit 3). Used: written 9.
SPBGPR                   = $d01b ; Sprite behind the background (bit n = sprite n). Used: written 2.
SPMC                     = $d01c ; Sprite multicolor mode (bit n = sprite n). Used: written 2.
XXPAND                   = $d01d ; Sprite double width (bit n = sprite n). Used: written 3.
SPSPCL                   = $d01e ; Sprite-sprite collision (bit n = sprite n). Reading clears it. Used: read 2.
EXTCOL                   = $d020 ; Border color (bits 0-3). Used: written 4.
BGCOL0                   = $d021 ; Background color 0 (bits 0-3). Used: written 6.
BGCOL1                   = $d022 ; Background color 1 (multicolor and extended color modes). Used: written 11.
BGCOL2                   = $d023 ; Background color 2 (multicolor and extended color modes). Used: written 4.
SP0COL                   = $d027 ; Sprite 0 color. Used: written 4.
SP1COL                   = $d028 ; Sprite 1 color. Used: written 1.
SP2COL                   = $d029 ; Sprite 2 color. Used: written 1.
SP3COL                   = $d02a ; Sprite 3 color. Used: written 1.
SP4COL                   = $d02b ; Sprite 4 color. Used: written 1.
SP6COL                   = $d02d ; Sprite 6 color. Used: written 1.
char_rom_chars_32_63     = $d100 ; Character ROM characters 32-63 (space, punctuation, digits), visible with $01 = $32; cold_start copies them to text_font. Used: read 1.

; SID registers $d400-$d7ff
FRELO1                   = $d400 ; SID voice 1 frequency, low byte. Write only. Used: written 6.
FREHI1                   = $d401 ; SID voice 1 frequency, high byte. Write only. Used: written 4.
PWLO1                    = $d402 ; SID voice 1 pulse width, low byte. Write only. Used: written 2.
PWHI1                    = $d403 ; SID voice 1 pulse width, high nybble. Write only. Used: written 2.
VCREG1                   = $d404 ; SID voice 1 control: gate (bit 0), sync (bit 1), ring modulation (bit 2), test (bit 3), waveform triangle/saw/pulse/noise (bits 4-7). Write only. Used: written 4.
ATDCY1                   = $d405 ; SID voice 1 attack (bits 4-7) and decay (bits 0-3). Write only. Used: written 2.
SUREL1                   = $d406 ; SID voice 1 sustain (bits 4-7) and release (bits 0-3). Write only. Used: written 2.
FRELO2                   = $d407 ; SID voice 2 frequency, low byte. Write only. Used: written 2.
FREHI2                   = $d408 ; SID voice 2 frequency, high byte. Write only. Used: written 2.
PWLO2                    = $d409 ; SID voice 2 pulse width, low byte. Write only. Used: written 1.
PWHI2                    = $d40a ; SID voice 2 pulse width, high nybble. Write only. Used: written 1.
VCREG2                   = $d40b ; SID voice 2 control: gate (bit 0), sync (bit 1), ring modulation (bit 2), test (bit 3), waveform triangle/saw/pulse/noise (bits 4-7). Write only. Used: written 3.
ATDCY2                   = $d40c ; SID voice 2 attack (bits 4-7) and decay (bits 0-3). Write only. Used: written 1.
SUREL2                   = $d40d ; SID voice 2 sustain (bits 4-7) and release (bits 0-3). Write only. Used: written 1.
FRELO3                   = $d40e ; SID voice 3 frequency, low byte. Write only. Used: written 4.
FREHI3                   = $d40f ; SID voice 3 frequency, high byte. Write only. Used: written 4.
PWLO3                    = $d410 ; SID voice 3 pulse width, low byte. Write only. Used: written 1.
PWHI3                    = $d411 ; SID voice 3 pulse width, high nybble. Write only. Used: written 1.
VCREG3                   = $d412 ; SID voice 3 control: gate (bit 0), sync (bit 1), ring modulation (bit 2), test (bit 3), waveform triangle/saw/pulse/noise (bits 4-7). Write only. Used: written 5.
ATDCY3                   = $d413 ; SID voice 3 attack (bits 4-7) and decay (bits 0-3). Write only. Used: written 1.
SUREL3                   = $d414 ; SID voice 3 sustain (bits 4-7) and release (bits 0-3). Write only. Used: written 1.
CUTLO                    = $d415 ; SID filter cutoff, bits 0-2. Write only. Used: written 1.
CUTHI                    = $d416 ; SID filter cutoff, bits 3-10. Write only. Used: written 1.
RESON                    = $d417 ; SID filter resonance (bits 4-7) and the voices through the filter (bits 0-3). Write only. Used: written 1.
SIGVOL                   = $d418 ; SID volume (bits 0-3) and filter mode (bits 4-7). Write only. Used: written 2.
RANDOM                   = $d41b ; Voice 3 oscillator output, often a random number source. Read only. Used: read 1, written 1.

; CIA 1 registers $dc00-$dcff
CIAPRA                   = $dc00 ; CIA 1: Port A: keyboard columns (write) and joystick 2 (read). Used: read 9, written 4.
CIAPRB                   = $dc01 ; CIA 1: Port B: keyboard rows (read) and joystick 1 (read). Used: read 11, written 1.
CIADDRA                  = $dc02 ; CIA 1: Data direction of port A (1 = output). Used: read 1, written 5.
CIADDRB                  = $dc03 ; CIA 1: Data direction of port B (1 = output). Used: read 1, written 6.
CIAICR                   = $dc0d ; CIA 1: Interrupt control: read gives the sources and clears them; write sets (bit 7 = 1) or clears (bit 7 = 0) the enable bits. Its interrupt goes to the IRQ line. Used: read 1, written 2.

; CIA 2 registers $dd00-$ddff
CI2PRA                   = $dd00 ; CIA 2: Port A: VIC-II bank (bits 0-1, inverted), serial bus and RS-232. Used: written 1.
CI2ICR                   = $dd0d ; CIA 2: Interrupt control: read gives the sources and clears them; write sets (bit 7 = 1) or clears (bit 7 = 0) the enable bits. Its interrupt goes to the NMI line. Used: read 1, written 2.

; I/O 1 $de00-$deff
; I/O area 1 for cartridges and expansions.
io1_dummy                = $de00 ; Unused I/O area 1: row_ptr_bottom points here so writes are lost; irq_entry (BRK branch, never taken) and the protection trap in update_high_score JMP through it, which crashes. Used: jumped through 2, address 3.
